"use strict";(self.webpackChunksig_m_adoc=self.webpackChunksig_m_adoc||[]).push([[244],{7759:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Introduction to SigMA","href":"/sigma/docs/intro","docId":"intro","unlisted":false},{"type":"category","label":"R Package","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Quick Start","href":"/sigma/docs/ForR/","docId":"ForR/index","unlisted":false},{"type":"link","label":"Installation","href":"/sigma/docs/ForR/installation","docId":"ForR/installation","unlisted":false},{"type":"link","label":"Parameter Choices","href":"/sigma/docs/ForR/parameter_choices","docId":"ForR/parameter_choices","unlisted":false},{"type":"link","label":"Optimize SigMA","href":"/sigma/docs/ForR/optimize","docId":"ForR/optimize","unlisted":false},{"type":"link","label":"MMRD Classification","href":"/sigma/docs/ForR/mmrd_classification","docId":"ForR/mmrd_classification","unlisted":false},{"type":"link","label":"FAQs","href":"/sigma/docs/ForR/faqs","docId":"ForR/faqs","unlisted":false},{"type":"category","label":"Advanced","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"System Architecture","href":"/sigma/docs/ForR/advanced/architecture","docId":"ForR/advanced/architecture","unlisted":false},{"type":"link","label":"assignment()","href":"/sigma/docs/ForR/advanced/assignment","docId":"ForR/advanced/assignment","unlisted":false},{"type":"link","label":"calc_cos() & cosine()","href":"/sigma/docs/ForR/advanced/calc_cos","docId":"ForR/advanced/calc_cos","unlisted":false},{"type":"link","label":"calc_llh()","href":"/sigma/docs/ForR/advanced/calc_llh","docId":"ForR/advanced/calc_llh","unlisted":false},{"type":"link","label":"Data Structures","href":"/sigma/docs/ForR/advanced/data_structures","docId":"ForR/advanced/data_structures","unlisted":false},{"type":"link","label":"decompose()","href":"/sigma/docs/ForR/advanced/decompose","docId":"ForR/advanced/decompose","unlisted":false},{"type":"link","label":"Options and Parameters","href":"/sigma/docs/ForR/advanced/option_parameters","docId":"ForR/advanced/option_parameters","unlisted":false},{"type":"link","label":"run()","href":"/sigma/docs/ForR/advanced/run","docId":"ForR/advanced/run","unlisted":false}],"href":"/sigma/docs/category/advanced"}],"href":"/sigma/docs/category/r-package"},{"type":"category","label":"Python Package","collapsible":true,"collapsed":true,"items":[{"type":"category","label":"Advanced","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Core Concepts & Architecture","href":"/sigma/docs/ForPython/advanced/sigmapy_architecture","docId":"ForPython/advanced/sigmapy_architecture","unlisted":false},{"type":"link","label":"Custom Pipeline Steps","href":"/sigma/docs/ForPython/advanced/custom_pipeline_steps","docId":"ForPython/advanced/custom_pipeline_steps","unlisted":false}],"href":"/sigma/docs/category/advanced-1"}],"href":"/sigma/docs/category/python-package"}]},"docs":{"ForPython/advanced/custom_pipeline_steps":{"id":"ForPython/advanced/custom_pipeline_steps","title":"Creating Custom Pipeline Steps","description":"This guide explains how to extend the sigmapy library by creating your own custom pipeline steps and how to integrate them into a Sigma pipeline. Understanding this process allows for flexible and tailored data processing workflows.","sidebar":"tutorialSidebar"},"ForPython/advanced/sigmapy_architecture":{"id":"ForPython/advanced/sigmapy_architecture","title":"SigMApy Core Concepts & Architecture","description":"This document provides an overview of the core classes and architectural design of the sigmapy library. Understanding these components can help users leverage SigMApy more effectively, customize its behavior, and contribute to its development.","sidebar":"tutorialSidebar"},"ForR/advanced/architecture":{"id":"ForR/advanced/architecture","title":"System Architecture","description":"This document describes the overall architecture of the SigMA project, including its directory structure, key components, and how they interact.","sidebar":"tutorialSidebar"},"ForR/advanced/assignment":{"id":"ForR/advanced/assignment","title":"assignment.R","description":"The R/assignment.R script contains the assignment() function. This function is responsible for assigning a binary status (e.g., positive/negative, pass/fail) for a specific mutational signature based on whether a calculated score exceeds predefined or custom thresholds. It translates quantitative scores into qualitative, actionable calls.","sidebar":"tutorialSidebar"},"ForR/advanced/calc_cos":{"id":"ForR/advanced/calc_cos","title":"calc_cos.R","description":"The R/calc_cos.R script provides functions to calculate cosine similarity, a common metric to measure the similarity between two non-zero vectors. In the context of mutational signatures, it is a fundamental method used to compare an observed mutational spectrum from a sample against a catalog of known reference signatures. A higher cosine similarity value indicates a greater resemblance between the sample\'s spectrum and the reference signature.","sidebar":"tutorialSidebar"},"ForR/advanced/calc_llh":{"id":"ForR/advanced/calc_llh","title":"calc_llh.R","description":"The R/calcllh.R script contains the calcllh() function. This function calculates a score related to the likelihood (specifically, a sum of log-likelihoods) of an observed mutational spectrum given a set of reference mutational signature probability distributions. It\'s a key method for assessing which reference signature or signature cluster best explains a sample\'s mutational pattern.","sidebar":"tutorialSidebar"},"ForR/advanced/data_structures":{"id":"ForR/advanced/data_structures","title":"Data Structures","description":"This document outlines the key data structures used as inputs to and produced as outputs by SigMA. It also touches upon important internal R object structures that SigMA relies upon, primarily loaded from sysdata.rda.","sidebar":"tutorialSidebar"},"ForR/advanced/decompose":{"id":"ForR/advanced/decompose","title":"decompose.R","description":"The R/decompose.R script provides the decompose() function, which is a sophisticated routine for determining the contribution of known mutational signatures to an observed mutational spectrum (spect). It employs a Non-Negative Least Squares (NNLS) algorithm within an iterative framework to find the combination of signatures and their exposures (activities) that best reconstructs the input spectrum, minimizing a Frobenius norm-based error.","sidebar":"tutorialSidebar"},"ForR/advanced/option_parameters":{"id":"ForR/advanced/option_parameters","title":"Options and Parameters","description":"This section provides a comprehensive guide to the various options and parameters available in SigMA, primarily focusing on the main run() function. Understanding these is crucial for customizing SigMA\'s behavior for specific analyses.","sidebar":"tutorialSidebar"},"ForR/advanced/run":{"id":"ForR/advanced/run","title":"run.R","description":"The R/run.R script defines the primary orchestrating function run()^. This function serves as the main entry point for executing the SigMA analysis pipeline. It integrates various computational steps, from data input and preprocessing to signature analysis, multivariate prediction, and results output. Its behavior is heavily controlled by a rich set of parameters.","sidebar":"tutorialSidebar"},"ForR/faqs":{"id":"ForR/faqs","title":"FAQs","description":"How can I use hg38?","sidebar":"tutorialSidebar"},"ForR/index":{"id":"ForR/index","title":"Quick Start","description":"While this documentation covers the R version of SigMA, we generally recommend using the Python version (SigMApy) for new projects due to its active development and more flexible workflow capabilities.","sidebar":"tutorialSidebar"},"ForR/installation":{"id":"ForR/installation","title":"Installation","description":"Download git-lfs//git-lfs.github.com/","sidebar":"tutorialSidebar"},"ForR/mmrd_classification":{"id":"ForR/mmrd_classification","title":"MMRD Classification","description":"This page covers how to perform MMRD (Mismatch Repair Deficiency) classification using SigMA and the required input file formats.","sidebar":"tutorialSidebar"},"ForR/optimize":{"id":"ForR/optimize","title":"Optimize SigMA","description":"For obtaining the best performance it is important that the simulations used in the tuning of the MVA models agree with the dataset that is being analyzed, therefore we added the functionality for the users to easily optimize SigMA parameters for their dataset.","sidebar":"tutorialSidebar"},"ForR/parameter_choices":{"id":"ForR/parameter_choices","title":"Parameter Choices","description":"You can train a classifier with SigMA without relying on built-in classifiers and for different choices of signature catalogs.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Introduction to SigMA","description":"SigMA is a robust framework specifically built for detecting Signature 3 (Sig3) \u2014 associated with homologous recombination deficiency (HRD) \u2014 even in low-mutation-count samples like targeted gene panels.","sidebar":"tutorialSidebar"}}}}')}}]);